mapper.select:
SELECT bp.*, dd.cn_name AS data_domain_cn_name FROM t_yak_ops_business_process bp LEFT JOIN t_yak_ops_data_domain dd ON bp.data_domain_id = dd.id
AND bp.en_short_name LIKE CONCAT('%', #{enShortName}, '%')
AND bp.cn_name LIKE CONCAT('%', #{cnName}, '%')
AND bp.en_name LIKE CONCAT('%', #{enName}, '%')
AND bp.data_domain_id = #{dataDomainId}
AND bp.director = #{director}
AND bp.create_by = #{createBy}
ORDER BY bp.flag DESC, bp.update_time DESC
